  v_chunk jsonb := $batch161_06$[{"id":"code-43275","kind":"paragraph","label":"43275","text":"43275 — Вакуум-камеры и циклоны для проведения процессов получения пластических масс; мельницы шаровые и стержневые в промышленности лаков и красок, пластмасс и анилиновой промышленности; сушилки барабанные, ленточные, вальцеленточные в промышленности лаков и красок; мельницы бисерные, песочные, ролико-маятниковые, аэробильные; диспергирующие машины (в том числе дисольверы, дисковые диспергаторы) в лакокрасочной и анилиновой промышленности; сушилки и смесовые барабаны в анилиновой промышленности\nНормативный срок службы: 10 лет.","level":3},{"id":"code-43276","kind":"paragraph","label":"43276","text":"43276 — Оборудование очистки газов фторорганических производств\nНормативный срок службы: 4 лет.","level":3},{"id":"code-43277","kind":"paragraph","label":"43277","text":"43277 — Установки воздухоразделительные производительностью свыше 1000 куб. м/ч по кислороду (свыше 5000 куб. м/ч по перерабатываемому воздуху)\nНормативный срок службы: 20 лет.","level":3},{"id":"code-43278","kind":"paragraph","label":"43278","text":"43278 — Экструдеры, аппараты отгонки мономеров, выпарные вакуумные установки, тянущие вальцы, машины резательные, газодувки для производства поликапроамидных нитей\nНормативный срок службы: 10 лет.","level":3},{"id":"code-43279","kind":"paragraph","label":"43279","text":"43279 — Аппараты с перемешивающими устройствами и смесители стальные, аппаратура из полимерных материалов для производства химических реактивов\nНормативный срок службы: 12 лет.","level":3},{"id":"code-43280","kind":"paragraph","label":"43280","text":"43280 — Машины литьевые, термопластавтоматы в производстве конструкционных материалов, смесители в производстве пресс-порошков\nНормативный срок службы: 10 лет.","level":3},{"id":"code-43281","kind":"paragraph","label":"43281","text":"43281 — Центрифуги и центробежные аппараты в производствах азотной промышленности, расплавители, автоклавы и аппар